(function(){
'use strict';
const root=document.querySelector('[data-pdf-tool]');if(!root)return;
const q=s=>root.querySelector(s),file=q('[data-file]'),drop=q('[data-drop]'),run=q('[data-run]'),reset=q('[data-reset]'),download=q('[data-download]'),err=q('[data-error]'),original=q('[data-original]'),result=q('[data-result]'),metrics=q('[data-metrics]'),progress=q('[data-progress]');
let selected=null,lastBlob=null,busy=false,cancelled=false,stateVersion=0,activeProcessVersion=0,autoTimer=null,pendingAuto=false,sourceLoadEpoch=0;const emitState=(reason='update')=>window.dispatchEvent(new CustomEvent('fastoolee:pdf-state',{detail:{mode:'compress',reason,files:selected?[selected]:[],selectedFile:selected||null,pageOrder:[],selectedPages:[],stateVersion}}));
const human=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(n<10240?1:0)+' KB':(n/1048576).toFixed(2)+' MB';
const error=t=>{err.textContent=t||'';err.hidden=!t;};
const val=n=>{const e=q(`[name="${n}"]`);return e?e.value:'';},checked=n=>{const e=q(`[name="${n}"]`);return !!(e&&e.checked)};
function showCancel(on){const c=q('[data-cancel]');if(!c)return;c.hidden=!on;c.setAttribute('aria-hidden',String(!on));}
function validTarget(){const n=parseFloat(val('target'));return Number.isFinite(n)&&n>0;}
function requestCompress(delay=100){clearTimeout(autoTimer);if(!selected||!validTarget())return;if(busy){pendingAuto=true;cancelled=true;return;}autoTimer=setTimeout(()=>{autoTimer=null;compress();},Math.max(0,delay));}
function setP(p,t){progress.hidden=false;const i=progress.querySelector('i');if(i)i.style.width=p+'%';const s=progress.querySelector('span');if(s)s.textContent=t||'';}
function libsReady(){return window.pdfjsLib&&window.PDFLib;}
async function ensureLibs(){if(libsReady())return;throw new Error('PDF engine is still loading. Please wait a moment and try again.');}
async function readInfo(f){await ensureLibs();const data=await f.arrayBuffer();const pdf=await pdfjsLib.getDocument({data}).promise;return{pages:pdf.numPages,pdf,data};}
async function choose(f){const loadEpoch=++sourceLoadEpoch;error('');selected=f;stateVersion++;if(busy){cancelled=true;pendingAuto=true;}lastBlob=null;result.hidden=true;window.dispatchEvent(new CustomEvent('fastoolee:pdf-clear'));if(!f||!((f.type==='application/pdf')||/\.pdf$/i.test(f.name||''))){selected=null;emitState('reset');error('Choose a PDF file.');return;}if(f.size>60*1024*1024){selected=null;emitState('reset');error('PDF is too large. Maximum file size is 60 MB.');return;}try{setP(8,'Reading PDF…');const info=await readInfo(f);if(loadEpoch!==sourceLoadEpoch){try{info.pdf?.destroy?.();}catch(_){}return;}original.hidden=false;original.innerHTML=`<strong>Original PDF</strong><span>${info.pages} page${info.pages===1?'':'s'}</span><span>${human(f.size)}</span>`;try{info.pdf?.destroy?.();}catch(_){}progress.hidden=true;emitState('source');requestCompress(30);}catch(e){if(loadEpoch!==sourceLoadEpoch)return;error(e.message||'Could not read this PDF.');progress.hidden=true;}}
file&&file.addEventListener('change',()=>file.files[0]&&choose(file.files[0]));if(drop){['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('is-drag')}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('is-drag')}));drop.addEventListener('drop',e=>{const f=e.dataTransfer.files&&e.dataTransfer.files[0];if(f)choose(f);});}
async function renderCompressed(info,dpi,quality,grayscale,onProgress){const out=await PDFLib.PDFDocument.create();const n=info.pages;for(let p=1;p<=n;p++){if(cancelled)throw new Error('Processing cancelled.');const page=await info.pdf.getPage(p),base=page.getViewport({scale:1}),scale=dpi/72,view=page.getViewport({scale});const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(view.width));canvas.height=Math.max(1,Math.round(view.height));const ctx=canvas.getContext('2d',{alpha:false,willReadFrequently:grayscale});ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);await page.render({canvasContext:ctx,viewport:view}).promise;if(grayscale){const img=ctx.getImageData(0,0,canvas.width,canvas.height),d=img.data;for(let i=0;i<d.length;i+=4){const y=Math.round(.299*d[i]+.587*d[i+1]+.114*d[i+2]);d[i]=d[i+1]=d[i+2]=y;}ctx.putImageData(img,0,0);}const blob=await new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(new Error('Could not encode a PDF page.')),'image/jpeg',quality));const bytes=await blob.arrayBuffer(),jpg=await out.embedJpg(bytes),op=out.addPage([base.width,base.height]);op.drawImage(jpg,{x:0,y:0,width:base.width,height:base.height});canvas.width=canvas.height=1;onProgress&&onProgress(p,n);await new Promise(r=>setTimeout(r,0));}return new Blob([await out.save({useObjectStreams:true})],{type:'application/pdf'});}
async function compress(){
 if(busy||!selected||!validTarget())return;
 clearTimeout(autoTimer);autoTimer=null;busy=true;pendingAuto=false;cancelled=false;activeProcessVersion=stateVersion;error('');lastBlob=null;result.hidden=true;window.dispatchEvent(new CustomEvent('fastoolee:pdf-clear'));showCancel(true);
 let info=null;try{
  await ensureLibs();const targetN=parseFloat(val('target')),target=targetN*(val('sizeunit')==='mb'?1048576:1024),pref=val('quality')||'balanced',floor=Math.max(72,parseInt(val('dpifloor')||'72',10)),gray=checked('grayscale');let dpi=pref==='best'?180:pref==='smallest'?110:145,qv=pref==='best'?.88:pref==='smallest'?.58:.74;info=await readInfo(selected);let best=null,bestSize=Infinity,attempt=0,finalDpi=dpi;
  for(;attempt<6;attempt++){
   if(cancelled)throw new Error('Processing cancelled.');setP(12+attempt*12,`Compression pass ${attempt+1}…`);const blob=await renderCompressed(info,dpi,qv,gray,(p,n)=>setP(12+attempt*12+(p/n)*10,`Pass ${attempt+1} · page ${p}/${n}`));if(blob.size<bestSize){best=blob;bestSize=blob.size;finalDpi=dpi;}if(blob.size<=target)break;if(dpi<=floor&&qv<=.38)break;dpi=Math.max(floor,Math.round(dpi*.84));qv=Math.max(.34,qv-.09);
  }
  if(activeProcessVersion!==stateVersion)return;
  lastBlob=best;const reached=best.size<=target,reduction=Math.max(0,(1-best.size/selected.size)*100);metrics.innerHTML=`<div class="metric-grid"><article><small>Requested</small><strong>≤ ${human(target)}</strong></article><article><small>Result</small><strong>${human(best.size)}</strong></article><article><small>Reduction</small><strong>${reduction.toFixed(1)}%</strong></article><article><small>Pages</small><strong>${info.pages}</strong></article><article><small>Status</small><strong class="${reached?'ok-text':'warn-text'}">${reached?'Target reached ✓':'Best achievable'}</strong></article><article><small>Final raster DPI</small><strong>${finalDpi} DPI</strong></article></div>${reached?'':'<p class="tool-note warn-note">The requested target could not be reached with the current quality floor. Try Smallest possible, grayscale, or a lower DPI floor.</p>'}<p class="tool-note">For reliable size reduction, pages are rebuilt as optimized images. Selectable text and links may become rasterized.</p>`;result.hidden=false;window.dispatchEvent(new CustomEvent('fastoolee:pdf-result',{detail:{blob:lastBlob,name:'fastoolee-compressed.pdf',mode:'compress'}}));setP(100,'Done');setTimeout(()=>progress.hidden=true,700);
 }catch(e){const stale=activeProcessVersion!==stateVersion;progress.hidden=true;if(!stale&&e.message!=='Processing cancelled.')error(e.message||'PDF compression failed.');}
 finally{try{info?.pdf?.destroy?.();}catch(_){}busy=false;showCancel(false);if(pendingAuto||activeProcessVersion!==stateVersion){pendingAuto=false;cancelled=false;requestCompress(140);}}
}
root.addEventListener('input',e=>{if(e.target.matches('input,select,textarea')&&e.target!==file){stateVersion++;lastBlob=null;result.hidden=true;window.dispatchEvent(new CustomEvent('fastoolee:pdf-clear'));emitState('settings');requestCompress(500);}});root.addEventListener('change',e=>{if(e.target.matches('input,select,textarea')&&e.target!==file){stateVersion++;lastBlob=null;result.hidden=true;window.dispatchEvent(new CustomEvent('fastoolee:pdf-clear'));emitState('settings');requestCompress(140);}});
showCancel(false);q('[data-cancel]')?.addEventListener('click',()=>{cancelled=true;pendingAuto=false;});download&&download.addEventListener('click',()=>{if(!lastBlob)return;const u=URL.createObjectURL(lastBlob),a=document.createElement('a');a.href=u;a.download='fastoolee-compressed.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);});reset&&reset.addEventListener('click',()=>{cancelled=true;pendingAuto=false;sourceLoadEpoch++;clearTimeout(autoTimer);autoTimer=null;selected=null;stateVersion++;lastBlob=null;file.value='';original.hidden=true;result.hidden=true;error('');progress.hidden=true;showCancel(false);window.dispatchEvent(new CustomEvent('fastoolee:pdf-clear'));emitState('reset');});
})();
